        {
            (long, long) key = (baseVtblIdLow, baseVtblIdHigh);
            Entry[] existing = s_entries.TryGetValue(
                key,
                out Entry[]? found)
                ? found
                : [];

            // Most-derived first, so a grandchild is preferred over
            // its parent when both answer IsObjectType.
